35	// repoAPI serves GET /repos/acme/private, answering through respond.
36	func repoAPI(t *testing.T, respond func(http.ResponseWriter, *http.Request)) *httptest.Server {
37		t.Helper()
38		server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
